result_name_template:
{{- /* DraCuLa Jellyfin: one-line media-source label. The head is length-capped and optional fields are added only while the label stays within 72 code points. */ -}}
{{- $b := 72 -}}
{{- $res := truncate 5 (replace (replace .Resolution "2160p" "4K") "1440p" "2K") -}}
{{- $qual := truncate 9 (replace .Quality "BluRay REMUX" "REMUX") -}}
{{- $hdr := "" -}}{{- if .HDR -}}{{- $hl := .HDR -}}{{- if gt (length $hl) 3 -}}{{- $hl = slice $hl 0 3 -}}{{- end -}}{{- $hdr = truncate 20 (join $hl "+") -}}{{- end -}}
{{- $head := "" -}}
{{- if .Library -}}{{- $head = "LIB" -}}{{- end -}}
{{- if and (or .Seasons .Complete) (not .Episode) (not .Episodes) -}}{{- $head = trim (printf "%s PACK" $head) -}}{{- end -}}
{{- if $res -}}{{- $head = trim (printf "%s %s" $head $res) -}}{{- end -}}
{{- if $qual -}}{{- $head = trim (printf "%s %s" $head $qual) -}}{{- end -}}
{{- if $hdr -}}{{- $head = trim (printf "%s %s" $head $hdr) -}}{{- end -}}
{{- if not $head -}}{{- $head = "Unknown" -}}{{- end -}}
{{- $size := "" -}}
{{- if .Size -}}{{- if lt .Size 1000000000 -}}{{- $size = size .Size -}}{{- else -}}{{- $t := div 100000000 (add 50000000 .Size) -}}{{- if ge $t 100 -}}{{- $size = printf "%d GB" (div 1000000000 (add 500000000 .Size)) -}}{{- else -}}{{- $size = printf "%d.%d GB" (div 10 $t) (mod 10 $t) -}}{{- end -}}{{- end -}}{{- end -}}
{{- $aud := "" -}}
{{- if .Audio -}}{{- $al := .Audio -}}{{- if gt (length $al) 2 -}}{{- $al = slice $al 0 2 -}}{{- end -}}{{- $aud = replace (replace (replace (replace (join $al " ") "Dolby Digital Plus" "DD+") "Dolby Digital" "DD") "DTS Lossless" "DTS-HD MA") "DTS Lossy" "DTS" -}}{{- end -}}
{{- if .Channels -}}{{- $aud = trim (printf "%s %s" $aud (index .Channels 0)) -}}{{- end -}}
{{- $lang := "" -}}
{{- if .Languages -}}{{- $ll := .Languages -}}{{- if gt (length $ll) 3 -}}{{- $ll = slice $ll 0 3 -}}{{- end -}}{{- $lang = upper (join $ll "/") -}}{{- if and (eq .LanguageSource "measured") (not (without .Probed.AudioLanguages .Languages)) -}}{{- $lang = printf "%s✓" $lang -}}{{- end -}}{{- if gt (length .Languages) 3 -}}{{- $lang = printf "%s +%d" $lang (sub 3 (length .Languages)) -}}{{- end -}}{{- end -}}
{{- if .DualAudio -}}{{- $lang = trim (printf "%s DUAL" $lang) -}}{{- end -}}
{{- $codec := trim (printf "%s %s" .Codec .BitDepth) -}}
{{- /* The group is the one free-text field: the field delimiter, line separators and the measured-language mark in it become spaces. */ -}}
{{- $grp := "" -}}{{- if .Group -}}{{- $g := trim (translate "·\n\r\u2028\u2029✓" "      " (replace .Group " · " " ")) -}}{{- if $g -}}{{- $grp = truncate 12 $g -}}{{- end -}}{{- end -}}
{{- $head -}}
{{$filledStars := replace (stars 5 .TopScoreWithoutResolution .ScoreWithoutResolution) "☆" ""}}{{if $filledStars}} {{$filledStars}}{{end}}
{{- $used := length $head -}}
{{- if $filledStars -}}{{- $used = add (add 1 (length $filledStars)) $used -}}{{- end -}}
{{- $tail := "" -}}
{{- if $size -}}{{- $n := add (add 3 (length $size)) $used -}}{{- if le $n $b -}}{{- $tail = printf "%s · %s" $tail $size -}}{{- $used = $n -}}{{- end -}}{{- end -}}
{{- if $aud -}}{{- $n := add (add 3 (length $aud)) $used -}}{{- if le $n $b -}}{{- $tail = printf "%s · %s" $tail $aud -}}{{- $used = $n -}}{{- end -}}{{- end -}}
{{- if $lang -}}{{- $n := add (add 3 (length $lang)) $used -}}{{- if le $n $b -}}{{- $tail = printf "%s · %s" $tail $lang -}}{{- $used = $n -}}{{- end -}}{{- end -}}
{{- if $codec -}}{{- $n := add (add 3 (length $codec)) $used -}}{{- if le $n $b -}}{{- $tail = printf "%s · %s" $tail $codec -}}{{- $used = $n -}}{{- end -}}{{- end -}}
{{- if $grp -}}{{- $n := add (add 3 (length $grp)) $used -}}{{- if le $n $b -}}{{- $tail = printf "%s · %s" $tail $grp -}}{{- $used = $n -}}{{- end -}}{{- end -}}
{{- $tail -}}
